def answer_query(image_patch: ImagePatch, query: str) -> str:
    # Split the query into individual words
    query_words = query.split()

    # Find the patches that match each word in the query
    patches = [image_patch.find(word) for word in query_words]

    # If all words in the query are found in the image
    if all(patches):
        # Return a positive answer
        return "yes"
    else:
        # If not all words are found, use the llm_query method to get an answer
        return image_patch.llm_query(f"Is there a {' '.join(query_words)} in the image?", long_answer=False)

