def answer_query(image, query):
    import numpy as np
    from typing import List

    def bool_to_yesno(bool_answer: bool) -> str:
        return "yes" if bool_answer else "no"

    image_patch = ImagePatch(image)
    man_patches = image_patch.find(query)

    if len(man_patches) == 0:
        return bool_to_yesno(False)

    man_patch = man_patches[0]
    color = man_patch.simple_query("What is the color?")
    if color:
        return f"The man is {color}."

    building_patches = image_patch.find("building")
    if len(building_patches) > 0:
        building_patch = building_patches[0]
        building_name = building_patch.simple_query("What is the name of the building?")
        if building_name:
            return man_patch.llm_query(f"What city is {building_name} in?", long_answer=False)

    return "The man's information is not available."

