def find_objects(image_patch: ImagePatch, objects: List[str]) -> List[ImagePatch]:
    """Find the objects in the image patch and return a list of patches for each object."""
    object_patches = []
    for obj in objects:
        object_patches.extend(image_patch.find(obj))
    return object_patches

def answer_query(image, query: str) -> str:
    """Answer a query about an image."""
    image_patch = ImagePatch(image)
    objects = query.split()
    object_patches = find_objects(image_patch, objects)
    if len(object_patches) != len(objects):
        return "One or more objects not found in the image."
    for patch in object_patches:
        if not patch.exists(patch.object_name):
            return f"{patch.object_name} not found in the image."
    return "All objects found in the image."

