def answer_query(image_patch: ImagePatch, query: str) -> str:
    # Split the query into words
    query_words = query.split()

    # Find the patches that match the query words
    patches = [image_patch]
    for word in query_words:
        new_patches = []
        for patch in patches:
            new_patches.extend(patch.find(word))
        if not new_patches:
            # If no patches match the current word, return a failure message
            return f"Could not find any {word} in the image."
        patches = new_patches

    # If multiple patches match the query, return a failure message
    if len(patches) > 1:
        return f"Found multiple instances of the query in the image. Please refine your query."

    # Use the llm_query method to answer the query
    return patches[0].llm_query(query, long_answer=False)

